// TypeScript: progressive stream consumer with fragment resume and tool idempotency
import { RedwoodStream } from 'redwood-sdk';

const s = new RedwoodStream({ apiKey: process.env.RW_KEY });

async function consume() {
  let resumeToken = await loadResume(); // may be null
  const session = s.openSession({ model: 'rw-13b', resume_token: resumeToken });

  for await (const msg of session.stream()) {
    // msg.shape: { type, data, fragment_index, resume_token, tool_event? }
    if (msg.type === 'resume') {
      await saveResume(msg.resume_token);
      continue;
    }

    if (msg.type === 'tool_event') {
      // tool_event contains idempotency_key and status
      const t = msg.tool_event;
      if (t.status === 'invocation_requested') {
        // dispatch to local tool runner; ensure idempotency by checking key
        await runToolOnce(t.idempotency_key, t.payload);
      }
    }

    if (msg.type === 'structured_chunk') {
      // incremental JSON fragments; merge into local accumulator
      mergeFragment(msg.fragment_index, msg.data);
    }
  }
}

// adapter for legacy sync clients
export async function syncAdapter(prompt) {
  const parts: string[] = [];
  const session = s.openSession({ model: 'rw-13b' });
  for await (const m of session.stream()) {
    if (m.type === 'structured_chunk') parts.push(m.data.text || '');
    if (m.type === 'complete') break;
  }
  return parts.join('');
}

