// Go: lightweight streamer with resume token handling and idempotent tool invocations
package sdkexamples

import ( 
  "context"
  "fmt"
  rw "github.com/redwood-inference/go-sdk"
)

func Consume(ctx context.Context) error {
  client := rw.NewClient("${RW_KEY}")
  resumeToken := LoadResume() // string or empty
  sess, err := client.OpenSession(ctx, rw.SessionOpts{Model: "rw-13b", ResumeToken: resumeToken})
  if err != nil { return err }
  for {
    msg, err := sess.Recv() // blocking receive of next event or io.EOF
    if err != nil { return err }
    if msg.Type == "resume" {
      SaveResume(msg.ResumeToken)
      continue
    }
    if msg.Type == "tool_event" {
      t := msg.ToolEvent
      if t.Status == "invocation_requested" {
        if !Seen(t.IdempotencyKey) {
          RunTool(t.Payload)
          MarkSeen(t.IdempotencyKey)
        }
      }
    }
    if msg.Type == "structured_chunk" {
      MergeFragment(msg.FragmentIndex, msg.Data)
    }
  }
  return nil
}
